    a[1] = 1
    a[2] = 1

    def get_a(n):
        if n not in a:
            raise ValueError(f"a_{n} not yet computed")
        return a[n]

    # Calculate up to n=16
    for n in range(3, 17):
        try:
            a_n_minus_1 = get_a(n - 1)

            # Recurrence: a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
            term1 = get_a(a_n_minus_1)
            term2 = get_a(n - a_n_minus_1)

            a[n] = term1 + term2
        except ValueError as e:
            print(f"Error calculating a_{n}: {e}")
            return

    # Print the sequence values for easy inspection
    results = [(n, a[n]) for n in range(1, 17)]
    print("n | a_n")
    print("---|----")
    for n, val in results:
        print(f"{n:2} | {val}")

solve()

